    # Straight vertical runs of the 5-colored guide.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            a = r
            while r + 1 < h and grid[r + 1][c] == 5:
                r += 1
            b = r
            r += 1
            if b - a + 1 < 2:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if not 0 <= nc < w:
                    continue
                active = [rr for rr in range(a, b + 1) if grid[rr][nc] not in (0, 5)]
                if not active:
                    continue
                # The pattern is the contiguous run of seed rows adjoining an end of the guide.
                if b in active:
                    lo = b
                    while lo - 1 in active:
                        lo -= 1
                    rows = list(range(lo, b + 1))
                elif a in active:
                    hi = a
                    while hi + 1 in active:
                        hi += 1
                    rows = list(range(a, hi + 1))
                else:
                    continue
                pats = []
                for rr in rows:
                    seq = []
                    cc = nc
                    while 0 <= cc < w and grid[rr][cc] not in (0, 5):
                        seq.append(grid[rr][cc])
                        cc += dc
                    pats.append(seq)
                width = min(map(len, pats))
                if not width:
                    continue
                for rr in range(a, b + 1):
                    seq = pats[(rr - a) % len(pats)]
                    for k in range(width):
                        out[rr][nc + dc * k] = seq[k]
    # Straight horizontal runs, the rotated version of the same rule.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            a = c
            while c + 1 < w and grid[r][c + 1] == 5:
                c += 1
            b = c
            c += 1
            if b - a + 1 < 2:
                continue
            for dr in (-1, 1):
                nr = r + dr
                if not 0 <= nr < h:
                    continue
                active = [cc for cc in range(a, b + 1) if grid[nr][cc] not in (0, 5)]
                if not active:
                    continue
                if a in active:
                    hi = a
                    while hi + 1 in active:
                        hi += 1
                    cols = list(range(a, hi + 1))
                elif b in active:
                    lo = b
                    while lo - 1 in active:
                        lo -= 1
                    cols = list(range(lo, b + 1))
                else:
                    continue
                pats = []
                for cc in cols:
                    seq = []
                    rr = nr
                    while 0 <= rr < h and grid[rr][cc] not in (0, 5):
                        seq.append(grid[rr][cc])
                        rr += dr
                    pats.append(seq)
                depth = min(map(len, pats))
                if not depth:
                    continue
                for cc in range(a, b + 1):
                    seq = pats[(cc - a) % len(pats)]
                    for k in range(depth):
                        out[nr + dr * k][cc] = seq[k]
    return out
